(4396599, 633504, 88642, '<td valign="top">omg! i LOVE it! great shot and title!</td>', 'omg! i LOVE it! great shot and title!', '2008-01-16 11:23:56.000000', NULL, 1),
(4396601, 633439, 86915, '<td valign="top">very cute! good choice of background colour</td>', 'very cute! good choice of background colour', '2008-01-16 11:24:08.000000', NULL, 1),
(4396602, 633159, 86915, '<td valign="top">i love this. great colour and great detail</td>', 'i love this. great colour and great detail', '2008-01-16 11:24:27.000000', NULL, 1),
(4396603, 633828, 69691, '<td valign="top">Good idea to use school busses for this challenge i was thinking about using the same subject. If i were to do this shot again i would try and capture either the whole bus or busses or capture the mid section of the bus because then   you would be focusing more on the yellow of the bus. This composition you see things that dont need to be seen to communicate the message that you want to and that message is just yellow.</td>', 'Good idea to use school busses for this challenge i was thinking about using the same subject. If i were to do this shot again i would try and capture either the whole bus or busses or capture the mid section of the bus because then   you would be focusing more on the yellow of the bus. This composition you see things that dont need to be seen to communicate the message that you want to and that message is just yellow.', '2008-01-16 11:24:27.000000', NULL, 1),
(4396605, 633930, 79955, '<td valign="top">Better post processing would definitely help this image. I would. Too overexposed</td>', 'Better post processing would definitely help this image. I would. Too overexposed', '2008-01-16 11:24:36.000000', NULL, 1),
