(4396610, 633546, 79955, '<td valign="top">Image too soft this time for my liking. I feel that the bokeh background is fighting too much with the droplet for my attention.</td>', 'Image too soft this time for my liking. I feel that the bokeh background is fighting too much with the droplet for my attention.', '2008-01-16 11:26:37.000000', NULL, 1),
