(4396617, 633923, 79955, '<td valign="top">Focus is off, need to have slightly more DOF also.</td>', 'Focus is off, need to have slightly more DOF also.', '2008-01-16 11:28:42.000000', NULL, 1),
(4396620, 631936, 88241, '<td valign="top">Nice warm lighting.</td>', 'Nice warm lighting.', '2008-01-16 11:29:08.000000', NULL, 1),
(4396621, 632053, 79955, '<td valign="top">Cool shot , well timed and captured</td>', 'Cool shot , well timed and captured', '2008-01-16 11:29:11.000000', NULL, 1),
(4396632, 632112, 88656, '<td valign="top">I really like how the picture is at an angle. I also really like the color of blue that the sky is behind the yellow car. It isn''t to destracting and i has nice contrast. Vroom Vroom! :)</td>', 'I really like how the picture is at an angle. I also really like the color of blue that the sky is behind the yellow car. It isn''t to destracting and i has nice contrast. Vroom Vroom! :)', '2008-01-16 11:30:32.000000', NULL, 1),
