(4396640, 633546, 88642, '<td valign="top">great shot! i really like the ''softness'' of it.</td>', 'great shot! i really like the ''softness'' of it.', '2008-01-16 11:31:49.000000', NULL, 1),
(4396641, 633756, 88656, '<td valign="top">Ayden is a very cute kid! I love his eyes in the picture! Good job!</td>', 'Ayden is a very cute kid! I love his eyes in the picture! Good job!', '2008-01-16 11:31:59.000000', NULL, 1),
(4396644, 633573, 69691, '<td valign="top">This is a great location for this challenge and this is a decent shot! It would have been nice if the blanket this person is holding would have been yellow to complement the nice yellow foreground. Maybe even get her to wear some more yellow! also the trees in the sky dont really add much they just draw your eye away from the subject. They arent really needed. I find the best images are when the distractions are minimized.</td>', 'This is a great location for this challenge and this is a decent shot! It would have been nice if the blanket this person is holding would have been yellow to complement the nice yellow foreground. Maybe even get her to wear some more yellow! also the trees in the sky dont really add much they just draw your eye away from the subject. They arent really needed. I find the best images are when the distractions are minimized.', '2008-01-16 11:32:23.000000', NULL, 1),
(4396645, 633793, 79955, '<td valign="top">I like your use of DOF in this image making it almost an abstract. Nice 6</td>', 'I like your use of DOF in this image making it almost an abstract. Nice 6', '2008-01-16 11:32:29.000000', NULL, 1),
(4396649, 631850, 88241, '<td valign="top">I''m not sure I get the Yellow part of this photo.  Otherwise very well done.</td>', 'I''m not sure I get the Yellow part of this photo.  Otherwise very well done.', '2008-01-16 11:34:29.000000', NULL, 1),
