(4396654, 632941, 88656, '<td valign="top">Haha I love kool-aid, and i love your picture! Wonderful idea!</td>', 'Haha I love kool-aid, and i love your picture! Wonderful idea!', '2008-01-16 11:35:21.000000', NULL, 1),
(4396655, 633829, 88241, '<td valign="top">A bit more contrast would have helped this shot.</td>', 'A bit more contrast would have helped this shot.', '2008-01-16 11:35:34.000000', NULL, 1),
