(4396661, 632906, 88241, '<td valign="top">This shot would have been better if the man on the right was in focus. Otherwise very nice.</td>', 'This shot would have been better if the man on the right was in focus. Otherwise very nice.', '2008-01-16 11:36:57.000000', NULL, 1),
