(4397493, 633505, 40464, '<td valign="top">Very nice branch pattern, sharp and well exposed. To bad you can still see a tree trough the fog in the lower right corner...</td>', 'Very nice branch pattern, sharp and well exposed. To bad you can still see a tree trough the fog in the lower right corner...', '2008-01-16 15:36:08.000000', NULL, 1),
(4397501, 633512, 40464, '<td valign="top">Nice shot, but I belive the edges of fire hidrant should not have been cropped.</td>', 'Nice shot, but I belive the edges of fire hidrant should not have been cropped.', '2008-01-16 15:40:56.000000', NULL, 1),
(4397502, 632611, 85886, '<td valign="top">Clever idea putting seed down for the birds near your props.  I hope you didn''t have to wait too long for this lovely great tit (at least that''s what we call them here I think - might get lost in translation!)</td>', 'Clever idea putting seed down for the birds near your props.  I hope you didn''t have to wait too long for this lovely great tit (at least that''s what we call them here I think - might get lost in translation!)', '2008-01-16 15:41:04.000000', NULL, 1),
(4397505, 633505, 85886, '<td valign="top">A really potent image.  I really like the fractal shapes the silhouetted branches make against the yellow haze/fog.</td>', 'A really potent image.  I really like the fractal shapes the silhouetted branches make against the yellow haze/fog.', '2008-01-16 15:42:32.000000', NULL, 1),
(4397506, 632488, 40464, '<td valign="top">If she continues blowig, it''s her eyes that will pop (out) :))) Nice pic, one of best in challenge so far.</td>', 'If she continues blowig, it''s her eyes that will pop (out) :))) Nice pic, one of best in challenge so far.', '2008-01-16 15:43:00.000000', NULL, 1),
