INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4397700, 633581, 77192, '<td valign="top">hmmm...I fancy a nice glass of white wine now. Or, as per your excellent suggestion, three!</td>', 'hmmm...I fancy a nice glass of white wine now. Or, as per your excellent suggestion, three!', '2008-01-16 17:03:16.000000', NULL, 1),
(4397704, 633811, 70689, '<td valign="top">cool shot. From the thumbnail I thought it was too dark, but it is not. Great lighting. 8</td>', 'cool shot. From the thumbnail I thought it was too dark, but it is not. Great lighting. 8', '2008-01-16 17:04:50.000000', NULL, 1),
