(4398387, 632846, 65234, '<td valign="top">Clever; nicely composed and lit with just a hint of a soft shadow.</td>', 'Clever; nicely composed and lit with just a hint of a soft shadow.', '2008-01-16 21:39:55.000000', NULL, 1),
(4398394, 633259, 65234, '<td valign="top">Looks a little shriveled but I have no idea what one is supposed to look like, and the light is doing a nice job of highlighting the texture.  Not entirely sure I like the crop but the berry''s quite nice.</td>', 'Looks a little shriveled but I have no idea what one is supposed to look like, and the light is doing a nice job of highlighting the texture.  Not entirely sure I like the crop but the berry''s quite nice.', '2008-01-16 21:44:35.000000', NULL, 1),
(4398395, 633331, 76335, '<td valign="top">I fear this will score poorly, but I like it a lot. Very artistic. An eight for you.</td>', 'I fear this will score poorly, but I like it a lot. Very artistic. An eight for you.', '2008-01-16 21:44:50.000000', NULL, 1),
(4398398, 633670, 65234, '<td valign="top">That''s rather elaborately yellow.</td>', 'That''s rather elaborately yellow.', '2008-01-16 21:45:43.000000', NULL, 1),
