(4398400, 633405, 65234, '<td valign="top">Like the rays but not the bright white areas.</td>', 'Like the rays but not the bright white areas.', '2008-01-16 21:46:36.000000', NULL, 1),
(4398406, 633125, 65234, '<td valign="top">Interesting with the varying water levels creating different patterns.</td>', 'Interesting with the varying water levels creating different patterns.', '2008-01-16 21:54:32.000000', NULL, 1),
(4398407, 633619, 49804, '<td valign="top">Incredible shot, love the composition, great expression, nice selective desaturation of sorts, very nicely done, 9</td>', 'Incredible shot, love the composition, great expression, nice selective desaturation of sorts, very nicely done, 9', '2008-01-16 21:57:17.000000', NULL, 1),
(4398408, 633546, 49804, '<td valign="top">Awesome shot, great composition, lovely colors, nicely done, 10 from me</td>', 'Awesome shot, great composition, lovely colors, nicely done, 10 from me', '2008-01-16 21:57:59.000000', NULL, 1),
(4398411, 632806, 65234, '<td valign="top">Nice detail on the eye; I can see the pupil.  Lovely color on him too.</td>', 'Nice detail on the eye; I can see the pupil.  Lovely color on him too.', '2008-01-16 21:58:47.000000', NULL, 1),
(4398416, 633049, 65234, '<td valign="top">Looks sunny and warm.  I like the subtle shadows on the wall.</td>', 'Looks sunny and warm.  I like the subtle shadows on the wall.', '2008-01-16 21:59:34.000000', NULL, 1),
(4398417, 633741, 65234, '<td valign="top">Bright.  Very bright.  Certainly could not drive past that place and miss seeing it, could you?</td>', 'Bright.  Very bright.  Certainly could not drive past that place and miss seeing it, could you?', '2008-01-16 22:00:08.000000', NULL, 1),
(4398418, 632247, 65234, '<td valign="top">Put a little sugar on it next time!</td>', 'Put a little sugar on it next time!', '2008-01-16 22:00:39.000000', NULL, 1),
(4398421, 632488, 65234, '<td valign="top">That is amazingly yellow.  I think I need to toddle off and find my sunglasses.</td>', 'That is amazingly yellow.  I think I need to toddle off and find my sunglasses.', '2008-01-16 22:04:50.000000', NULL, 1),
(4398424, 632701, 65234, '<td valign="top">The old-fashioned kind.</td>', 'The old-fashioned kind.', '2008-01-16 22:05:35.000000', NULL, 1),
(4398425, 631257, 65234, '<td valign="top">Creative, and gooey.</td>', 'Creative, and gooey.', '2008-01-16 22:05:57.000000', NULL, 1),
(4398429, 633956, 65234, '<td valign="top">Very pretty scene.  Blue looks a little oversaturated but it does set off the red rocks well.</td>', 'Very pretty scene.  Blue looks a little oversaturated but it does set off the red rocks well.', '2008-01-16 22:07:23.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4398432, 633233, 65234, '<td valign="top">It has a spider on it.  That is the first thing I noticed, but then I may be a wee bit paranoid about them.</td>', 'It has a spider on it.  That is the first thing I noticed, but then I may be a wee bit paranoid about them.', '2008-01-16 22:08:27.000000', NULL, 1),
(4398435, 633072, 65234, '<td valign="top">That''s a train for grownups?  Loks like playground colors.</td>', 'That''s a train for grownups?  Loks like playground colors.', '2008-01-16 22:09:17.000000', NULL, 1),
(4398437, 632697, 65234, '<td valign="top">Someone''s been chewing on him by the looks of those dents.  Why is he still smiling?</td>', 'Someone''s been chewing on him by the looks of those dents.  Why is he still smiling?', '2008-01-16 22:10:02.000000', NULL, 1),
(4398438, 633624, 65234, '<td valign="top">Nicely sparkly.</td>', 'Nicely sparkly.', '2008-01-16 22:10:37.000000', NULL, 1),
(4398439, 633124, 65234, '<td valign="top">The eyes are lovely and the light on the cat is very nice to bring out all the detail on her fur and whiskers.  For this particular challenge you might have been better off with a solid background, preferably in a golden yellow to match his/her eyes, or a much tighter crop to leave out the competing colors.</td>', 'The eyes are lovely and the light on the cat is very nice to bring out all the detail on her fur and whiskers.  For this particular challenge you might have been better off with a solid background, preferably in a golden yellow to match his/her eyes, or a much tighter crop to leave out the competing colors.', '2008-01-16 22:13:00.000000', NULL, 1),
(4398442, 633903, 65234, '<td valign="top">That''s really nice.  Simple, great choice of background color, well lit and nicely detailed.</td>', 'That''s really nice.  Simple, great choice of background color, well lit and nicely detailed.', '2008-01-16 22:14:06.000000', NULL, 1),
(4398447, 632476, 65234, '<td valign="top">On my monitor the flower petals are orange and the center is brown.  I''m having trouble finding any yellow.  I like her expression and the shot is not bad, but I can''t vote it very high if I can''t find any yellow when there are some great shots in this challenge that do have yellow.  Sorry.</td>', 'On my monitor the flower petals are orange and the center is brown.  I''m having trouble finding any yellow.  I like her expression and the shot is not bad, but I can''t vote it very high if I can''t find any yellow when there are some great shots in this challenge that do have yellow.  Sorry.', '2008-01-16 22:17:04.000000', NULL, 1),
(4398449, 633120, 65234, '<td valign="top">Nice take on this.  Looks almost like a chocolate banana.</td>', 'Nice take on this.  Looks almost like a chocolate banana.', '2008-01-16 22:17:49.000000', NULL, 1),
(4398452, 633915, 65234, '<td valign="top">Wow, Post-Its can be pretty when you arrange and light them properly!</td>', 'Wow, Post-Its can be pretty when you arrange and light them properly!', '2008-01-16 22:19:09.000000', NULL, 1),
(4398455, 633505, 65234, '<td valign="top">The yellow cast works well in this scene.</td>', 'The yellow cast works well in this scene.', '2008-01-16 22:20:59.000000', NULL, 1),
(4398461, 633123, 65234, '<td valign="top">Nicely arranged.</td>', 'Nicely arranged.', '2008-01-16 22:23:43.000000', NULL, 1),
(4398469, 633298, 65234, '<td valign="top">Like the composition and clarity.  I can just feel those little petals straining to open.</td>', 'Like the composition and clarity.  I can just feel those little petals straining to open.', '2008-01-16 22:25:40.000000', NULL, 1),
(4398470, 633177, 41800, '<td valign="top">very yellow but lacks composition. Simple is sometimes better. You dont have to fill the frame as it leads to a busy shot. Having 3 bright objects in the foreground leads to confusion of what the main subject is. Having the yellow balls in the foreground with a sharp focus and the streamers in the background with a blurred focus might of shown off your subject more and would give it a more composed look. Your lighting looks pretty good with nice contrast. Blue is not complimentary to yellow but it is to orange. The shaded steamer do have an orange tinge to them so I guess so it works but I still would of cropped the little blue square in the top right.</td>', 'very yellow but lacks composition. Simple is sometimes better. You dont have to fill the frame as it leads to a busy shot. Having 3 bright objects in the foreground leads to confusion of what the main subject is. Having the yellow balls in the foreground with a sharp focus and the streamers in the background with a blurred focus might of shown off your subject more and would give it a more composed look. Your lighting looks pretty good with nice contrast. Blue is not complimentary to yellow but it is to orange. The shaded steamer do have an orange tinge to them so I guess so it works but I still would of cropped the little blue square in the top right.', '2008-01-16 22:25:43.000000', NULL, 1),
(4398471, 633643, 65234, '<td valign="top">Nice find for this challenge.</td>', 'Nice find for this challenge.', '2008-01-16 22:25:59.000000', NULL, 1),
(4398482, 633171, 65234, '<td valign="top">I am going to have that title stuck in my head, I just know it!  This shot would make a fabulous jigsaw puzzle!</td>', 'I am going to have that title stuck in my head, I just know it!  This shot would make a fabulous jigsaw puzzle!', '2008-01-16 22:29:45.000000', NULL, 1),
(4398484, 633773, 88204, '<td valign="top">Very simple and clean. Grat focus and sharpness. Snow adds an unusual touch.</td>', 'Very simple and clean. Grat focus and sharpness. Snow adds an unusual touch.', '2008-01-16 22:30:14.000000', NULL, 1),
(4398487, 632204, 65234, '<td valign="top">That''s a really bright house.  Must be easy to find, day or night.</td>', 'That''s a really bright house.  Must be easy to find, day or night.', '2008-01-16 22:30:46.000000', NULL, 1),
(4398488, 633830, 88204, '<td valign="top">Good idea. I like the white background. Skin seems a tad washed out.</td>', 'Good idea. I like the white background. Skin seems a tad washed out.', '2008-01-16 22:30:53.000000', NULL, 1),
(4398495, 633504, 65234, '<td valign="top">Oops, some of them are a little tipsy.  Must be quite a party!</td>', 'Oops, some of them are a little tipsy.  Must be quite a party!', '2008-01-16 22:33:11.000000', NULL, 1),
(4398496, 633505, 88204, '<td valign="top">Great image. I love the ambience of the fog. I''ve tried shots like this and can''t make them work, so hats off to you. Great sharpness, defnition and depth from the fog. I get the feeling the yellow isn''t natural, i.e. you changed the hue in Photoshop. That''s fine but it diminishes a touch for me. Nice work overall.</td>', 'Great image. I love the ambience of the fog. I''ve tried shots like this and can''t make them work, so hats off to you. Great sharpness, defnition and depth from the fog. I get the feeling the yellow isn''t natural, i.e. you changed the hue in Photoshop. That''s fine but it diminishes a touch for me. Nice work overall.', '2008-01-16 22:33:15.000000', NULL, 1),
(4398498, 632736, 65234, '<td valign="top">Like the motion in this and the shadow is fabulous.</td>', 'Like the motion in this and the shadow is fabulous.', '2008-01-16 22:33:38.000000', NULL, 1),
(4398505, 633799, 65234, '<td valign="top">A lava lamp!  Fun :-)</td>', 'A lava lamp!  Fun :-)', '2008-01-16 22:34:43.000000', NULL, 1),
(4398509, 633049, 41800, '<td valign="top">Sharp, good DOF, and it''s yellowish. Shadows in the lighting do not add to this photo</td>', 'Sharp, good DOF, and it''s yellowish. Shadows in the lighting do not add to this photo', '2008-01-16 22:36:09.000000', NULL, 1),
(4398512, 631401, 88204, '<td valign="top">Interesting shot. I''m not sure I get the blur and the yellow but I like it. Eyes are not sharp but I still like it. I assume the blur was intentional and I have to guess the yellow cast was a hue adjustment. All said, it still draws my attention.</td>', 'Interesting shot. I''m not sure I get the blur and the yellow but I like it. Eyes are not sharp but I still like it. I assume the blur was intentional and I have to guess the yellow cast was a hue adjustment. All said, it still draws my attention.', '2008-01-16 22:36:48.000000', NULL, 1),
(4398516, 632918, 88204, '<td valign="top">Very yellow, nice location but not particularly inspiring for me. Maybe simplify the background or move the subject off center.</td>', 'Very yellow, nice location but not particularly inspiring for me. Maybe simplify the background or move the subject off center.', '2008-01-16 22:37:49.000000', NULL, 1),
(4398520, 633939, 88204, '<td valign="top">Ooh... very nice. I love how the whole frame is filled with yellow. Great sharpness up front and I like how the focus fades. Very striking. A tad oversharpened on the edges of the front petals.</td>', 'Ooh... very nice. I love how the whole frame is filled with yellow. Great sharpness up front and I like how the focus fades. Very striking. A tad oversharpened on the edges of the front petals.', '2008-01-16 22:38:46.000000', NULL, 1),
(4398522, 631078, 65234, '<td valign="top">Like the lighting, especially that nice twinkle on the glass.  Very festive, cheery image.</td>', 'Like the lighting, especially that nice twinkle on the glass.  Very festive, cheery image.', '2008-01-16 22:38:52.000000', NULL, 1),
