INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4399263, 630983, 5364, '<td valign="top">The lighting is a bit flat</td>', 'The lighting is a bit flat', '2008-01-17 07:35:20.000000', NULL, 1),
(4399265, 633410, 5364, '<td valign="top">This would have been striking if it weren''t for the bushes in the foreground</td>', 'This would have been striking if it weren''t for the bushes in the foreground', '2008-01-17 07:37:02.000000', NULL, 1),
(4399279, 632893, 67258, '<td valign="top">I presume the yellow is the bacground.  i am afraid that for me it just doesn''t work, and gives the appearance of an ''off'' white-balance.</td>', 'I presume the yellow is the bacground.  i am afraid that for me it just doesn''t work, and gives the appearance of an ''off'' white-balance.', '2008-01-17 07:57:50.000000', NULL, 1),
(4399280, 633120, 67258, '<td valign="top">Clever juxtaposition of colour - bold and graphic.</td>', 'Clever juxtaposition of colour - bold and graphic.', '2008-01-17 07:58:15.000000', NULL, 1),
(4399281, 633505, 67258, '<td valign="top">Very subtle - and very beautiful.</td>', 'Very subtle - and very beautiful.', '2008-01-17 07:59:34.000000', NULL, 1),
(4399296, 632291, 67258, '<td valign="top">I like this a great deal.  I do wish thre was just a little more room to the rigt so that the edge of the shutter was visible.</td>', 'I like this a great deal.  I do wish thre was just a little more room to the rigt so that the edge of the shutter was visible.', '2008-01-17 08:15:42.000000', NULL, 1),
(4399301, 633111, 67258, '<td valign="top">Had you waited just a second or two until the pedestrian was against the green of the trees I think you would have had a stronger photo.</td>', 'Had you waited just a second or two until the pedestrian was against the green of the trees I think you would have had a stronger photo.', '2008-01-17 08:17:36.000000', NULL, 1),
(4399309, 633380, 67258, '<td valign="top">I''m not a doggie person, but this appeals - excellent focus on the eyes.</td>', 'I''m not a doggie person, but this appeals - excellent focus on the eyes.', '2008-01-17 08:19:29.000000', NULL, 1),
(4399315, 633298, 78062, '<td valign="top">Great depth of field and great focus and comp. The only criticism i have is that it might be a bit too ''muddy'' in the middle of the tonal range, maybe by bringing in the levels a bit more on the right side it would give it a bit more pop? I''m nitpicking of course, but most people seem to prefer that to platitudes. Great shot though. Looks very summery.</td>', 'Great depth of field and great focus and comp. The only criticism i have is that it might be a bit too ''muddy'' in the middle of the tonal range, maybe by bringing in the levels a bit more on the right side it would give it a bit more pop? I''m nitpicking of course, but most people seem to prefer that to platitudes. Great shot though. Looks very summery.', '2008-01-17 08:27:53.000000', NULL, 1),
(4399317, 631755, 78062, '<td valign="top">Not very yellow... nice shto though I suppose. More like a snapshot but i guess in 10 years it will be special to you.</td>', 'Not very yellow... nice shto though I suppose. More like a snapshot but i guess in 10 years it will be special to you.', '2008-01-17 08:28:37.000000', NULL, 1),
(4399318, 633830, 78062, '<td valign="top">nice idea. There''s a lot of empty space that doesn''t really do much for the image though... maybe if the umbrella filled the side of the frame and she was peeking around it? I dunno... also, i think some saturation would be great here too to make it pop a bit more and make it a bit livelier.</td>', 'nice idea. There''s a lot of empty space that doesn''t really do much for the image though... maybe if the umbrella filled the side of the frame and she was peeking around it? I dunno... also, i think some saturation would be great here too to make it pop a bit more and make it a bit livelier.', '2008-01-17 08:29:50.000000', NULL, 1),
(4399321, 633738, 78062, '<td valign="top">Interesting... i don''t think I like the cropping at the top though, how it missed the ends of the branches. I like the colours though. Focus is good, comp is good... it just doesn''t do enough for me. 1 more thing: is that sand?</td>', 'Interesting... i don''t think I like the cropping at the top though, how it missed the ends of the branches. I like the colours though. Focus is good, comp is good... it just doesn''t do enough for me. 1 more thing: is that sand?', '2008-01-17 08:31:08.000000', NULL, 1),
(4399324, 632747, 78062, '<td valign="top">nice idea. A lot of flowers in this challenge. I think it needs something more to make it stand out though, maybe some curves usage or somehting similar. Also, it looks a bit more sand coloured than actual yellow, but still, it''s nice.</td>', 'nice idea. A lot of flowers in this challenge. I think it needs something more to make it stand out though, maybe some curves usage or somehting similar. Also, it looks a bit more sand coloured than actual yellow, but still, it''s nice.', '2008-01-17 08:32:00.000000', NULL, 1),
