(4409482, 633610, 81382, '<td valign="top">Amazing colours and lighting. A non textured surface would perhaps have been a simpler choice - a smoked mirror for example taken off the wall and layed down flat would have been ideal</td>', 'Amazing colours and lighting. A non textured surface would perhaps have been a simpler choice - a smoked mirror for example taken off the wall and layed down flat would have been ideal', '2008-01-21 08:53:59.000000', NULL, 1),
(4409488, 633929, 81382, '<td valign="top">Nice complementary colours working well together, good job on the freeze frame, its hard to setup and difficult to control so well done on that front. The viewpoint is the only thing letting this down for me, much closer to the water and more wide angle would have been more dramatic and would have added extra interest.</td>', 'Nice complementary colours working well together, good job on the freeze frame, its hard to setup and difficult to control so well done on that front. The viewpoint is the only thing letting this down for me, much closer to the water and more wide angle would have been more dramatic and would have added extra interest.', '2008-01-21 08:55:53.000000', NULL, 1),
(4409489, 632098, 81382, '<td valign="top">Nice and simple, superb lighting and interesting concept. Good entry</td>', 'Nice and simple, superb lighting and interesting concept. Good entry', '2008-01-21 08:56:28.000000', NULL, 1),
