(4411720, 631850, 83358, '<td valign="top">NOT REALLY ANYTHING TO DO WITH YELLOW IS IT? NETHERTHELESS A GREAT SHOT, YOU CAN ALMOST FEEL THE ATMOSPHERE.</td>', 'NOT REALLY ANYTHING TO DO WITH YELLOW IS IT? NETHERTHELESS A GREAT SHOT, YOU CAN ALMOST FEEL THE ATMOSPHERE.', '2008-01-21 19:34:37.000000', NULL, 1),
(4411845, 631706, 87539, '<td valign="top">It would be better more in focus.</td>', 'It would be better more in focus.', '2008-01-21 20:09:01.000000', NULL, 1),
(4411884, 633610, 87539, '<td valign="top">Very interesting idea! The surface under the toy looks like it''s tilting down towards the right just a tiny bit, but I think it adds to the overall character of the photo.</td>', 'Very interesting idea! The surface under the toy looks like it''s tilting down towards the right just a tiny bit, but I think it adds to the overall character of the photo.', '2008-01-21 20:23:10.000000', NULL, 1),
